shell_commands:
cd src/orchestration && python3 - <<'EOF'
p='orchestratorHelpers.test.ts'
s=open(p).read()
s=s.replace("import {shouldContinueToolLoop} from './orchestratorHelpers.js';","import {addRoundUsage, shouldContinueToolLoop} from './orchestratorHelpers.js';")
s=s.replace("import type {ToolCall} from '../types/ai.js';","import type {ToolCall, UsageMetadata} from '../types/ai.js';")
s+="""
describe('addRoundUsage', () => {
  it('sums the rounds that reported usage and skips a round that reported none', () => {
    const rounds: Array<UsageMetadata | undefined> = [
      {inputTokens: 2, outputTokens: 1, totalTokens: 3},
      undefined,
      {inputTokens: 7, outputTokens: 4, totalTokens: 11},
    ];

    expect(rounds.reduce(addRoundUsage, undefined)).toEqual({inputTokens: 9, outputTokens: 5, totalTokens: 14});
  });
});
"""
open(p,'w').write(s)
EOF
cd ../.. && timeout 300 node --experimental-vm-modules node_modules/jest/bin/jest.js --runTestsByPath src/orchestration/orchestratorHelpers.test.ts 2>&1 | tail -20

cat >> src/orchestration/orchestratorHelpers.ts <<'EOF'

/** Adds one provider call's usage to the turn's running total; a call that reported none leaves the total unchanged. */
export function addRoundUsage(
  total: UsageMetadata | undefined,
  round: UsageMetadata | undefined
): UsageMetadata | undefined {
  if (!round) return total;
  if (!total) return round;
  return {
    inputTokens: total.inputTokens + round.inputTokens,
    outputTokens: total.outputTokens + round.outputTokens,
    totalTokens: total.totalTokens + round.totalTokens,
  };
}
EOF
npx prettier --write src/orchestration/orchestratorHelpers.ts src/orchestration/orchestratorHelpers.test.ts
timeout 300 node --experimental-vm-modules node_modules/jest/bin/jest.js --runTestsByPath src/orchestration/orchestratorHelpers.test.ts 2>&1 | grep -E "Tests:|✓|✕"
